//===- Version.cpp - csl++ release and build information ------------------===//
//
// VersionInfo.inc is generated by CMake from the build's CSL_RELEASE_VERSION,
// CSL_GIT_COMMIT and CSL_LLVM_REVISION, which the Conan build sets.
//
//===----------------------------------------------------------------------===//

#include "csl-mlir/Dialect/CSL/Utils/Version.h"
#include "llvm/Config/llvm-config.h"

#include "VersionInfo.inc"

using namespace mlir;

llvm::StringRef csl::getReleaseVersion() { return CSL_RELEASE_VERSION; }

llvm::StringRef csl::getGitCommit() { return CSL_GIT_COMMIT; }

void csl::printVersion(llvm::raw_ostream &os, llvm::StringRef toolName) {
  llvm::StringRef release = getReleaseVersion();
  llvm::StringRef commit = getGitCommit();
  os << toolName << " (csl++) "
     << (release.empty() ? "development build" : release) << "\n";
  os << "  commit " << (commit.empty() ? "unknown" : commit) << "\n";
  os << "  LLVM " << LLVM_VERSION_STRING;
  llvm::StringRef llvmRevision = CSL_LLVM_REVISION;
  if (!llvmRevision.empty())
    os << ", revision " << llvmRevision;
  os << "\n";
#ifndef NDEBUG
  os << "  assertions enabled\n";
#else
  os << "  assertions disabled\n";
#endif
}
